            if not np.isnan(float(s)): 
                nm=NAMES[int(s)]
                if w in m and m[w]!=nm: print('CONFLICT',kn,w,m[w],nm)
                m[w]=nm
    b=v[0][2]
    uw=set(b['UniqWalls'].tolist())
    if not uw<=set(m): print('UNMAPPED',kn, uw-set(m), [x[0] for x in v]); unmapped+=1
    CL[float(b['Corridor_Length'])]+=1; TL[float(b['Texture_Length'])]+=1; GL[float(b['Gray_Space_length'])]+=1
print('unmapped sessions',unmapped)
print('CL',CL); print('TL',TL); print('GL',GL)
