arguments.command:
python - <<'EOF'
import numpy as np, collections
ei=np.load('data/beh/Imaging_Exp_info.npy',allow_pickle=1).item()
Beh={k:np.load('data/beh/Beh_%s.npy'%k,allow_pickle=1).item() for k in ei}
info=collections.OrderedDict()
for et,db in ei.items():
    for d in db:
        kn='%s_%s_%s'%(d['mname'],d['datexp'],d['blk'])
        key=kn+('_'+d['stimtype'] if 'stimtype' in d else '')
        info.setdefault(kn,[]).append((et,key,Beh[et][key]))
dur=[]
for kn,v in info.items():
    b=v[0][2]
    mask=b['ft_CorrSpc']&(b['ft_move']>0)&~np.isnan(b['ft_trInd'])
    fr=np.where(mask)[0]; tr=b['ft_trInd'][fr].astype(int)
    for t in np.unique(tr):
        f=fr[tr==t]
        if len(f)>=5: dur.append((b['ft'][f[-1]]-b['Trial_start_time'][t])*86400)
dur=np.array(dur)
print(len(dur), np.percentile(dur,[50,75,90,95,99,99.5,100]))
for th in [30,60,120,300]:
    print(th, (dur>th).mean())
EOF

